import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

PENDING = {"n": 0}

class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _send(self, code, body, ctype="text/plain"):
        data = body.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/metrics":
            self._send(200,
                "# HELP demo_pending_work Items waiting to be processed\n"
                "# TYPE demo_pending_work gauge\n"
                'demo_pending_work{namespace="demo"} %d\n' % PENDING["n"])
        elif u.path == "/work/add":
            try:
                PENDING["n"] += int(q.get("items", ["10"])[0])
            except ValueError:
                pass
            self._send(200, str(PENDING["n"]))
        elif u.path == "/work/take":
            try:
                take = int(q.get("items", ["2"])[0])
            except ValueError:
                take = 2
            PENDING["n"] = max(0, PENDING["n"] - take)
            self._send(200, str(PENDING["n"]))
        else:
            self._send(404, "not found")

ThreadingHTTPServer(("0.0.0.0", 9101), H).serve_forever()
